// Range — Gtk.Range
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles range with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"

export interface RangeProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** Adjustment, from Gtk.Range */
  adjustment?: ReactNode

  /** gdouble, from Gtk.Range */
  fillLevel?: number

  /** gboolean, from Gtk.Range */
  inverted?: boolean

  /** gboolean, from Gtk.Range */
  restrictToFillLevel?: boolean

  /** gint, from Gtk.Range */
  roundDigits?: number

  /** gboolean, from Gtk.Range */
  showFillLevel?: boolean
}

export function Range({ className, children }: RangeProps) {
  return (
    <div className={cn(className)}>
      {children}
    </div>
  )
}
